import { useState, type FormEvent } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton } from '@jinx-ui/react';

export interface ProfileSettings {
  name: string;
  language: string;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  initialSettings?: ProfileSettings;
  onSave: (settings: ProfileSettings) => void;
}

const LANGUAGE_OPTIONS = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

export default function ProfileSettingsForm({
  initialSettings,
  onSave,
}: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState(initialSettings?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.emailNotifications ?? false,
  );
  const [submitted, setSubmitted] = useState(false);

  const trimmedName = name.trim();
  const nameError =
    submitted && trimmedName.length === 0 ? 'Укажите имя' : undefined;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSubmitted(true);
    if (trimmedName.length === 0) return;
    onSave({ name: trimmedName, language, emailNotifications });
  };

  return (
    <form
      onSubmit={handleSubmit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 20,
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxInputField
        label="Имя"
        name="name"
        required
        autoComplete="name"
        placeholder="Как к вам обращаться"
        value={name}
        onChange={(event) => setName(event.target.value)}
        errorText={nameError}
        helperText="Имя видно другим участникам"
      />

      <JxSelect
        label="Язык интерфейса"
        options={LANGUAGE_OPTIONS}
        value={language}
        onValueChange={setLanguage}
      />

      <JxSwitch
        label="Уведомления на почту"
        name="emailNotifications"
        checked={emailNotifications}
        onChange={(event) => setEmailNotifications(event.target.checked)}
      />

      <div style={{ display: 'flex', gap: 8 }}>
        <JxButton variant="primary" type="submit">
          Сохранить
        </JxButton>
      </div>
    </form>
  );
}

